<div class="page-heading"><div><span class="eyebrow">EXPORT DES DONNÉES</span><h1>Exporter en CSV</h1><p>Le fichier est encodé en UTF-8 avec BOM et s’ouvre directement dans Excel.</p></div><a class="button secondary" href="?r=results">← Retour</a></div><section class="panel export-panel"><form method="get" action="" id="export-form"><input type="hidden" name="r" value="export"><input type="hidden" name="ids" value="<?=e($export_ids)?>"><input type="hidden" name="columns" id="export-columns" value=""><div class="panel-heading"><div><h2>Colonnes à inclure</h2><p><?= $export_ids!==''?'Export des prospects sélectionnés':'Export de tous les prospects' ?></p></div><label class="inline-check"><input type="checkbox" id="export-all" checked> Tout sélectionner</label></div><div class="export-options"><?php foreach(['nom'=>'Nom','categorie'=>'Catégorie','adresse'=>'Adresse','ville'=>'Ville','code_postal'=>'Code postal','telephone'=>'Téléphone','email'=>'Email','facebook'=>'Facebook','instagram'=>'Instagram','site_web_statut'=>'Statut du site','score_confiance'=>'Confiance','statut_prospection'=>'Statut prospection','latitude'=>'Latitude','longitude'=>'Longitude','created_at'=>'Date d’ajout'] as $key=>$label):?><label class="check-line"><input type="checkbox" class="export-column" value="<?=e($key)?>" checked><span><?=e($label)?></span></label><?php endforeach;?></div><button class="button primary">↓ Télécharger le fichier CSV</button></form></section>
<script>document.getElementById('export-form').addEventListener('submit',function(){document.getElementById('export-columns').value=Array.from(document.querySelectorAll('.export-column:checked')).map(x=>x.value).join(',')});document.getElementById('export-all').addEventListener('change',function(){document.querySelectorAll('.export-column').forEach(x=>x.checked=this.checked)});document.querySelectorAll('.export-column').forEach(x=>x.addEventListener('change',function(){document.getElementById('export-all').checked=Array.from(document.querySelectorAll('.export-column')).every(y=>y.checked)}));</script>
